import type { ProjectModel } from '../analysis/types.ts';
import type { ResolvedConfig } from '../config/resolved.ts';
import type { Severity } from '../diagnostics/types.ts';
import type { SourceRef } from '../ir/types.ts';
import { TOOL_NAME } from '../meta.ts';
import type { JsDocTarget } from '../plugins/types.ts';
import { ImportManager, type Lang } from './imports.ts';
import type { GeneratedExport, JsDocBlock, JsDocTag } from './types.ts';

/** Marker present in the header of every generated file; used to recognise owned files. */
export const GENERATED_MARKER = `@generated by ${TOOL_NAME}`;

/** Plugin hooks composed by the plugin runner; plain functions without `this`. */
export interface CodegenHooks {
  jsdoc?: (block: JsDocBlock, target: JsDocTarget) => JsDocBlock;
  resolveImport?: (request: { from: string; to: string; specifier: string }) => string | undefined;
}

/** A problem found while generating code, located in the specification by its source. */
export interface CodegenDiagnostic {
  readonly code: string;
  readonly severity: Exclude<Severity, 'error'>;
  readonly message: string;
  readonly source?: SourceRef;
  readonly hint?: string;
}

export interface EmitContext {
  readonly project: ProjectModel;
  readonly config: ResolvedConfig;
  readonly hooks: CodegenHooks;
  /** Receives generator diagnostics; absent when code is rendered for display only. */
  readonly report?: (diagnostic: CodegenDiagnostic) => void;
}

/** One logical module, rendered for one or more languages. */
export interface ModuleOutput {
  /** Output-relative path without extension. */
  readonly module: string;
  readonly origin: string;
  readonly ts: string;
  readonly js: string;
  readonly dts: string;
  readonly exports: readonly GeneratedExport[];
  readonly sources?: {
    readonly operations?: readonly string[];
    readonly schemas?: readonly string[];
  };
}

export function header(config: ResolvedConfig): string {
  const lines = [
    '/* eslint-disable */',
    `// ${GENERATED_MARKER}. Do not edit: this file is overwritten on the next generation.`,
  ];
  if (config.output.banner !== undefined) {
    for (const line of config.output.banner.replace(/[\u2028\u2029\r]/g, '\n').split('\n')) {
      lines.push(`// ${line}`.trimEnd());
    }
  }
  return `${lines.join('\n')}\n`;
}

export function importExtension(config: ResolvedConfig): string {
  const option = config.output.importExtension;
  if (option === 'none') return '';
  if (option === '.ts' && config.output.language === 'typescript') return '.ts';
  return '.js';
}

/**
 * Renders a module in one language. `body` receives a fresh import manager and returns the code
 * that follows the imports.
 */
export function renderModule(
  module: string,
  lang: Lang,
  ctx: EmitContext,
  body: (imports: ImportManager) => string,
): string {
  const resolve = ctx.hooks.resolveImport;
  const imports = new ImportManager(module, lang, {
    extension: importExtension(ctx.config),
    ...(resolve === undefined ? {} : { resolve }),
  });
  const code = body(imports)
    .replace(/\n{3,}/g, '\n\n')
    .trimEnd();
  const importBlock = imports.render();
  // A file without imports or exports would be a script (and its JSDoc typedefs global).
  const isModule = importBlock !== '' || /^export /m.test(code);
  const parts = [header(ctx.config), importBlock, code, isModule ? '' : 'export {};'];
  return `${parts.filter((p) => p !== '').join('\n')}\n`;
}

/** Renders all three language variants of a module. */
export function renderAll(
  module: string,
  ctx: EmitContext,
  body: (imports: ImportManager, lang: Lang) => string,
): { ts: string; js: string; dts: string } {
  return {
    ts: renderModule(module, 'ts', ctx, (imports) => body(imports, 'ts')),
    js: renderModule(module, 'js', ctx, (imports) => body(imports, 'js')),
    dts: renderModule(module, 'dts', ctx, (imports) => body(imports, 'dts')),
  };
}

/** JSDoc tags that carry types in JavaScript output (`@param {Pet} params`), not documentation. */
const TYPE_TAGS: ReadonlySet<string> = new Set([
  'param',
  'returns',
  'typedef',
  'property',
  'template',
  'type',
]);

const isTypeTag = (tag: JsDocTag): boolean =>
  TYPE_TAGS.has(tag.tag) &&
  tag.text !== undefined &&
  tag.text.startsWith('{') &&
  !tag.text.startsWith('{@');

export function applyJsDocHook(
  ctx: EmitContext,
  block: JsDocBlock,
  target: JsDocTarget,
): JsDocBlock {
  // Without documentation, deprecations and the types JavaScript output needs are kept.
  if (!ctx.config.features.jsdoc)
    return { tags: block.tags.filter((t) => t.tag === 'deprecated' || isTypeTag(t)) };
  return ctx.hooks.jsdoc?.(block, target) ?? block;
}
